SELECT p.EDATE AS `截止日期`, c.COMCNNAME AS `公司中文名称`, c.COMCNABB AS `公司中文简称`, CONCAT(s.STKCODE, '.HK') AS `股票代码`, s.STKABB AS `股票简称`, ROUND(p.TMKCAP / 100000000, 1) AS `总市值(亿)` FROM HK_IDC_STKPFMIDC p INNER JOIN HK_STKCODE s ON p.STKUNICODE = s.STKUNICODE AND s.ISVALID = 1 AND s.LSSTUREFC = 1 AND s.TRMKREFC = 7 AND (s.STKTYREFC = 1 OR s.STKTYREFC = 6) AND LEFT(s.STKCODE, 1) != '8' INNER JOIN HK_COMBINFO c ON s.COMUNIC = c.COMUNIC AND c.ISVALID = 1 INNER JOIN VIEW_HK_INDUSTRY_TRACK t ON s.STKUNICODE = t.STKUNICODE WHERE p.EDATE = '2026-09-02' AND p.ISVALID = 1 AND t.SW_INDU_CODE_2021_1 = '非银金融' AND c.COMCNABB LIKE '%香港交易所%' AND p.TMKCAP IS NOT NULL ORDER BY p.EDATE DESC LIMIT 1;
